import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { AlertTriangle, ArrowDownUp, Boxes, Download, Package, PackageCheck, Search, Warehouse } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Badge, EmptyState, Modal, PageHeader, Progress, StatCard, cn } from '../lib/ui';
import { formatUZS, type Product } from '../lib/mock';

export const Inventory = () => {
  const { t } = useTranslation();
  const { products, categories, adjustStock, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState('all');
  const [editing, setEditing] = useState<Product | null>(null);
  const [newStock, setNewStock] = useState(0);
  const [reason, setReason] = useState('restock');

  const filtered = useMemo(() => {
    let list = [...products];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((p) => `${p.name} ${p.sku}`.toLowerCase().includes(q));
    if (filter === 'low') list = list.filter((p) => p.stock > 0 && p.stock <= 10);
    if (filter === 'out') list = list.filter((p) => p.stock === 0);
    if (filter === 'ok') list = list.filter((p) => p.stock > 10);
    return list.sort((a, b) => a.stock - b.stock);
  }, [products, query, filter]);

  const totalUnits = products.reduce((s, p) => s + p.stock, 0);
  const value = products.reduce((s, p) => s + p.stock * p.price, 0);
  const low = products.filter((p) => p.stock > 0 && p.stock <= 10).length;
  const out = products.filter((p) => p.stock === 0).length;

  const openAdjust = (p: Product) => {
    setEditing(p);
    setNewStock(p.stock);
    setReason('restock');
  };

  const save = () => {
    if (!editing) return;
    adjustStock(editing.id, Math.max(0, newStock));
    notify(`${editing.name}: ${t('updated')}`);
    setEditing(null);
  };

  const exportCsv = () => {
    const rows = [
      ['SKU', 'Product', 'Stock', 'Unit', 'Value'],
      ...filtered.map((p) => [p.sku, p.name, String(p.stock), p.unit, String(p.stock * p.price)]),
    ];
    const csv = rows.map((r) => r.map((v) => `"${v}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'maxshop-inventory.csv';
    a.click();
    URL.revokeObjectURL(url);
    notify('CSV yuklab olindi', 'info');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('inventoryTitle')}
        subtitle={t('inventorySubtitle')}
        action={
          <button className="btn-secondary btn-sm" onClick={exportCsv}>
            <Download size={15} /> {t('export')}
          </button>
        }
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Ombor birliklari" value={String(totalUnits)} icon={<Warehouse size={20} />} />
        <StatCard label={t('inventoryValue')} value={formatUZS(value)} icon={<Boxes size={20} />} tone="violet" />
        <StatCard label={t('lowStock')} value={String(low)} icon={<AlertTriangle size={20} />} tone="amber" />
        <StatCard label={t('outOfStock')} value={String(out)} icon={<Package size={20} />} tone="sky" />
      </div>

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-4">
        <div className="card p-5 xl:col-span-3">
          <div className="mb-4 flex flex-col gap-2 sm:flex-row">
            <div className="relative flex-1">
              <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
              <input className="input pl-10" placeholder="Mahsulot yoki SKU qidirish..." value={query} onChange={(e) => setQuery(e.target.value)} />
            </div>
            <select className="select sm:w-44" value={filter} onChange={(e) => setFilter(e.target.value)}>
              <option value="all">{t('all')}</option>
              <option value="ok">{t('inStock')}</option>
              <option value="low">{t('lowStock')}</option>
              <option value="out">{t('outOfStock')}</option>
            </select>
          </div>

          {filtered.length === 0 ? (
            <EmptyState title={t('noData')} />
          ) : (
            <div className="table-wrap">
              <table className="data-table min-w-[720px]">
                <thead>
                  <tr>
                    <th>{t('product')}</th>
                    <th>{t('category')}</th>
                    <th className="w-48">Zaxira</th>
                    <th>{t('status')}</th>
                    <th>Qiymat</th>
                    <th className="text-right">{t('actions')}</th>
                  </tr>
                </thead>
                <tbody>
                  {filtered.map((p) => {
                    const tone: 'danger' | 'warning' | 'success' = p.stock === 0 ? 'danger' : p.stock <= 10 ? 'warning' : 'success';
                    const cat = categories.find((c) => c.id === p.categoryId);
                    return (
                      <tr key={p.id}>
                        <td>
                          <div className="flex items-center gap-3">
                            <span className={cn('flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br text-lg', p.gradient)}>{p.emoji}</span>
                            <div>
                              <p className="text-xs font-extrabold">{p.name}</p>
                              <p className="text-[10px] text-[var(--muted)]">{p.sku}</p>
                            </div>
                          </div>
                        </td>
                        <td><Badge tone="neutral">{cat?.icon} {cat?.name}</Badge></td>
                        <td>
                          <div className="flex items-center gap-2">
                            <Progress value={(p.stock / 200) * 100} tone={p.stock === 0 ? 'rose' : p.stock <= 10 ? 'amber' : 'brand'} />
                            <span className="w-12 shrink-0 text-right text-[11px] font-extrabold">{p.stock} {p.unit}</span>
                          </div>
                        </td>
                        <td><Badge tone={tone}>{p.stock === 0 ? t('outOfStock') : p.stock <= 10 ? t('lowStock') : t('inStock')}</Badge></td>
                        <td className="text-xs font-bold">{formatUZS(p.stock * p.price)}</td>
                        <td>
                          <div className="flex justify-end">
                            <button className="btn-secondary btn-sm" onClick={() => openAdjust(p)}>
                              <ArrowDownUp size={13} /> {t('adjust')}
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="space-y-4">
          <div className="card p-5">
            <h3 className="font-display text-base font-extrabold">Tez tuzatish kerak</h3>
            <p className="mt-0.5 text-xs text-[var(--muted)]">Zaxirasi kritik darajada</p>
            <div className="mt-4 space-y-2">
              {products.filter((p) => p.stock <= 10).slice(0, 6).map((p) => (
                <button key={p.id} onClick={() => openAdjust(p)} className="flex w-full items-center gap-2.5 rounded-xl border p-2 text-left transition hover:bg-[var(--surface-2)]" style={{ borderColor: 'var(--border)' }}>
                  <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--surface-3)] text-base">{p.emoji}</span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-[11px] font-bold">{p.name}</p>
                    <p className={cn('text-[10px] font-extrabold', p.stock === 0 ? 'text-rose-500' : 'text-amber-500')}>{p.stock} {p.unit} qoldi</p>
                  </div>
                  <ArrowDownUp size={13} className="text-[var(--muted)]" />
                </button>
              ))}
            </div>
          </div>

          <div className="card overflow-hidden p-5">
            <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-brand-500/15 text-brand-600 dark:text-brand-300">
              <PackageCheck size={20} />
            </div>
            <h3 className="mt-3 font-display text-base font-extrabold">Ombor holati yaxshi</h3>
            <p className="mt-1 text-xs leading-relaxed text-[var(--muted)]">
              {products.length - low - out} ta mahsulot yetarli zaxiraga ega. Kam qolgan mahsulotlarni o'z vaqtida to'ldiring.
            </p>
            <div className="mt-3 flex items-center justify-between text-[10px] font-bold text-[var(--muted)]">
              <span>Sog'lom zaxira</span>
              <span>{Math.round(((products.length - low - out) / products.length) * 100)}%</span>
            </div>
            <div className="mt-1.5">
              <Progress value={((products.length - low - out) / products.length) * 100} />
            </div>
          </div>
        </div>
      </div>

      <Modal
        open={!!editing}
        onClose={() => setEditing(null)}
        title={t('adjustStock')}
        subtitle={editing?.name}
      >
        {editing && (
          <div className="space-y-4">
            <div className="flex items-center gap-3 rounded-2xl border p-3" style={{ borderColor: 'var(--border)' }}>
              <span className={cn('flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br text-2xl', editing.gradient)}>{editing.emoji}</span>
              <div>
                <p className="text-sm font-extrabold">{editing.name}</p>
                <p className="text-xs text-[var(--muted)]">{editing.sku} · {t('currentStock')}: <b>{editing.stock} {editing.unit}</b></p>
              </div>
            </div>
            <div>
              <label className="label">{t('newStock')}</label>
              <div className="flex items-center gap-2">
                <button className="icon-btn h-11 w-11" onClick={() => setNewStock((v) => Math.max(0, v - 1))}>−</button>
                <input type="number" className="input text-center text-lg font-extrabold" value={newStock} onChange={(e) => setNewStock(Number(e.target.value))} />
                <button className="icon-btn h-11 w-11" onClick={() => setNewStock((v) => v + 1)}>+</button>
              </div>
              <div className="mt-2 flex gap-1.5">
                {[10, 25, 50, 100].map((n) => (
                  <button key={n} className="btn-secondary btn-sm flex-1" onClick={() => setNewStock((v) => v + n)}>+{n}</button>
                ))}
              </div>
            </div>
            <div>
              <label className="label">{t('reason')}</label>
              <select className="select" value={reason} onChange={(e) => setReason(e.target.value)}>
                <option value="restock">Yangi partiya keldi</option>
                <option value="sale">Qo'lda sotuv</option>
                <option value="damage">Shikastlangan</option>
                <option value="return">Qaytarilgan</option>
                <option value="audit">Inventarizatsiya</option>
              </select>
            </div>
            <div className="flex gap-2">
              <button className="btn-secondary flex-1" onClick={() => setEditing(null)}>{t('cancel')}</button>
              <button className="btn-primary flex-1" onClick={save}>{t('save')}</button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};
